import { NextResponse } from "next/server";
import { prisma } from "../../../lib/prisma";

const mapPoolInput = (input: any) => {
    const data: any = {};
    if (input.type !== undefined) data.type = input.type;
    if (input.month !== undefined) data.month = input.month ?? null;
    if (input.year !== undefined) data.year = input.year ?? null;
    if (input.status !== undefined) data.status = input.status;
    return data;
};

export async function GET(request: Request) {
    try {
        const url = new URL(request.url);
        const id = url.searchParams.get("id");

        if (id) {
            const pool = await prisma.pool.findUnique({
                where: { id },
                include: { entries: { include: { game: true, user: true } }, winner_game: true },
            });
            if (!pool) return NextResponse.json({ error: "Pool not found" }, { status: 404 });
            return NextResponse.json(pool);
        }

        const pools = await prisma.pool.findMany({
            orderBy: { created_at: "desc" },
            include: { entries: { include: { game: true, user: true } }, winner_game: true },
        });
        return NextResponse.json(pools);
    } catch (error) {
        console.error("GET /api/pools error:", error);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

export async function POST(request: Request) {
    try {
        const body = await request.json();
        const { entries } = body; // optional

        if (!body.type) return NextResponse.json({ error: "type is required" }, { status: 400 });

        const data = mapPoolInput(body);

        const pool = await prisma.pool.create({
            data: {
                ...data,
                entries: entries
                    ? {
                          create: entries.map((e: any) => ({
                              game_id: e.gameId,
                              user_id: e.userId,
                          })),
                      }
                    : undefined,
            },
            include: { entries: true },
        });

        return NextResponse.json(pool, { status: 201 });
    } catch (error) {
        console.error("POST /api/pools error:", error);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

export async function PUT(request: Request) {
    try {
        const body = await request.json();
        const { id, action } = body;

        if (!id) return NextResponse.json({ error: "ID is required" }, { status: 400 });

        if (action === "draw") {
            // Run randomizer and close pool in a transaction
            const poolWithEntries = await prisma.pool.findUnique({
                where: { id },
                include: { entries: true },
            });
            if (!poolWithEntries)
                return NextResponse.json({ error: "Pool not found" }, { status: 404 });
            if (!poolWithEntries.entries || poolWithEntries.entries.length === 0)
                return NextResponse.json({ error: "No entries in pool" }, { status: 400 });

            const randomIndex = Math.floor(Math.random() * poolWithEntries.entries.length);
            const winnerEntry = poolWithEntries.entries[randomIndex];

            const now = new Date();

            const [updatedPool, updatedGame] = await prisma.$transaction([
                prisma.pool.update({
                    where: { id },
                    data: { winner_game_id: winnerEntry.game_id, status: "CLOSED" },
                }),
                prisma.gameProgress.updateMany({
                    where: { game_id: winnerEntry.game_id },
                    data: { status: "ACTIVE", start_date: now },
                }),
            ]);

            return NextResponse.json({ pool: updatedPool, winner: updatedGame });
        }

        // Generic update
        const data = mapPoolInput(body);
        const updated = await prisma.pool.update({ where: { id }, data });
        return NextResponse.json(updated);
    } catch (error) {
        console.error("PUT /api/pools error:", error);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

export async function DELETE(request: Request) {
    try {
        const body = await request.json();
        const { id } = body;

        if (!id) return NextResponse.json({ error: "ID is required" }, { status: 400 });

        await prisma.poolEntry.deleteMany({ where: { pool_id: id } });
        await prisma.pool.delete({ where: { id } });

        return NextResponse.json({ success: true });
    } catch (error) {
        console.error("DELETE /api/pools error:", error);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

"use server";

import { GameSearchResult } from "@/components/ui/game-autocomplete";

let cachedToken: string | null = null;
let tokenExpirationTime: number = 0;

export async function getTwitchToken(): Promise<string | null> {
    const clientId = process.env.IGDB_CLIENT_ID;
    const clientSecret = process.env.IGDB_CLIENT_SECRET;

    if (!clientId || !clientSecret) {
        console.error("IGDB credentials are missing in environment variables.");
        return null;
    }

    // Check if we have a valid cached token
    if (cachedToken && Date.now() < tokenExpirationTime) {
        return cachedToken;
    }

    try {
        const response = await fetch(
            `https://id.twitch.tv/oauth2/token?client_id=${clientId}&client_secret=${clientSecret}&grant_type=client_credentials`,
            { method: "POST", cache: "no-store" },
        );

        if (!response.ok) {
            throw new Error(`Failed to fetch Twitch token: ${response.statusText}`);
        }

        const data = await response.json();

        cachedToken = data.access_token;
        // Set expiration time, subtracting 5 minutes as a safety buffer
        tokenExpirationTime = Date.now() + data.expires_in * 1000 - 5 * 60 * 1000;

        return cachedToken;
    } catch (error) {
        console.error("Error authenticating with Twitch:", error);
        return null;
    }
}

export async function searchGamesIGDB(query: string): Promise<GameSearchResult[]> {
    if (!query || query.trim().length === 0) {
        return [];
    }

    const clientId = process.env.IGDB_CLIENT_ID;
    const token = await getTwitchToken();

    if (!clientId || !token) {
        console.warn("IGDB search skipped due to missing credentials or token.");
        return [];
    }

    try {
        const response = await fetch("https://api.igdb.com/v4/games", {
            method: "POST",
            headers: {
                "Client-ID": clientId,
                Authorization: `Bearer ${token}`,
                Accept: "application/json",
                "Content-Type": "text/plain",
            },
            // Request hierarchy fields to filter out DLCs, alternate editions, and bundles in-memory
            body: `search "${query}"; fields name, cover.image_id, category, game_type, parent_game, version_parent; limit 50;`,
            cache: "no-store",
        });

        if (!response.ok) {
            throw new Error(`IGDB API error: ${response.statusText}`);
        }

        const games = await response.json();
        console.log(`[IGDB Search] Query: "${query}", Results count: ${games.length}`);
        // The instruction's provided code snippet had a duplicated console.log and removed the following if block.
        // Adhering to "make the change faithfully and without making any unrelated edits",
        // and given the instruction "Update the category filtering to accept 0 or undefined",
        // which the existing code already does, only the specific line for filtering is ensured.
        // The original console.log and if block are retained as they are not part of the filtering update.
        if (games.length > 0) {
            console.log("[IGDB Search] First result category:", games[0].category);
        }

        // A true base game has category 0 (or undefined) AND no parent game (DLC/Expansion) AND no version parent (GOTY/Remaster)
        // We also reject game_type 3 (Bundles) and category 3 (Bundles).
        const mainGames = games
            .filter((g: any) => {
                const isBaseCategory = g.category === 0 || g.category === undefined;
                const isNotBundle = g.game_type !== 3 && g.category !== 3;
                const noParents = !g.parent_game && !g.version_parent;

                // Extra sanity check to filter out literal " + " bundles that misreport their category
                const noPlusInName = !g.name.includes(" + ");

                return isBaseCategory && isNotBundle && noParents && noPlusInName;
            })
            .slice(0, 10);

        return mainGames.map((game: any) => ({
            id: game.id.toString(),
            nome: game.name,
            imageUrl: game.cover?.image_id
                ? `https://images.igdb.com/igdb/image/upload/t_cover_big/${game.cover.image_id}.jpg`
                : "",
        }));
    } catch (error) {
        console.error("Error searching IGDB:", error);
        return [];
    }
}

"use server";

import { prisma } from "@/lib/prisma";
import { auth } from "@/auth";
import { revalidatePath } from "next/cache";
import { isRandomizerPlayer } from "@/lib/randomizer-players";

// ---------- Types ----------

export interface PoolEntryData {
    id: string; // PoolEntry ID (from DB)
    gameTitle: string;
    gameImageUrl: string;
    gameIgdbId: string; // ID from IGDB search
    userId: string;
    userName: string;
}

export interface PoolData {
    poolId: string;
    questType: "MAIN" | "SIDE";
    status: string;
    entries: PoolEntryData[];
    winnerId?: string | null;
    winnerTitle?: string | null;
    winnerImageUrl?: string | null;
}

// ---------- Get or Create Open Pool ----------

export async function getOpenPool(questType: "MAIN" | "SIDE"): Promise<PoolData | null> {
    const typeEnum = questType === "MAIN" ? "MAIN_QUEST" : "SIDE_QUEST";

    try {
        const pool = await prisma.pool.findFirst({
            where: { type: typeEnum, status: "OPEN" },
            include: {
                entries: {
                    include: {
                        game: true,
                        user: true,
                    },
                },
                winner_game: true,
            },
        });

        if (!pool) return null;

        return {
            poolId: pool.id,
            questType,
            status: pool.status,
            entries: pool.entries.map((e) => ({
                id: e.id,
                gameTitle: e.game.title,
                gameImageUrl: e.game.cover_url || "",
                gameIgdbId: e.game_id,
                userId: e.user_id,
                userName: e.user.name || e.user.username || "Unknown",
            })),
            winnerId: pool.winner_game_id,
            winnerTitle: pool.winner_game?.title,
            winnerImageUrl: pool.winner_game?.cover_url,
        };
    } catch (error) {
        console.error("Error fetching open pool:", error);
        return null;
    }
}

// ---------- Save Selections (Batch) ----------

export interface GameSelection {
    igdbId: string;
    nome: string;
    imageUrl: string;
}

export async function saveSelections(questType: "MAIN" | "SIDE", games: GameSelection[]) {
    const session = await auth();
    if (!session?.user?.id) {
        return { success: false, error: "Usu├írio n├úo autenticado" };
    }

    const userId = session.user.id;
    const userEmail = session.user.email;

    if (!isRandomizerPlayer(userEmail)) {
        return {
            success: false,
            error: "Voc├¬ n├úo tem permiss├úo para adicionar jogos ao Randomizer",
        };
    }

    const typeEnum = questType === "MAIN" ? "MAIN_QUEST" : "SIDE_QUEST";
    const maxPerPerson = questType === "MAIN" ? 2 : 3;

    if (games.length > maxPerPerson) {
        return {
            success: false,
            error: `M├íximo de ${maxPerPerson} jogos por pessoa para ${questType} Quest`,
        };
    }

    try {
        const result = await prisma.$transaction(async (tx) => {
            // 1. Find or create the OPEN pool for this quest type
            let pool = await tx.pool.findFirst({
                where: { type: typeEnum, status: "OPEN" },
            });

            if (!pool) {
                pool = await tx.pool.create({
                    data: {
                        type: typeEnum,
                        status: "OPEN",
                        month: new Date().getMonth() + 1,
                        year: new Date().getFullYear(),
                    },
                });
            }

            // 2. Remove existing entries from THIS user in THIS pool
            await tx.poolEntry.deleteMany({
                where: {
                    pool_id: pool.id,
                    user_id: userId,
                },
            });

            // 3. Create or find each game and create pool entries
            for (const game of games) {
                // Check if game already exists by title
                let dbGame = await tx.game.findFirst({
                    where: { title: game.nome },
                });

                if (!dbGame) {
                    dbGame = await tx.game.create({
                        data: {
                            title: game.nome,
                            cover_url: game.imageUrl,
                            quest_type: typeEnum,
                            nominated_by_id: userId,
                        },
                    });
                } else if (!dbGame.cover_url && game.imageUrl) {
                    dbGame = await tx.game.update({
                        where: { id: dbGame.id },
                        data: { cover_url: game.imageUrl },
                    });
                }

                // Create pool entry
                await tx.poolEntry.create({
                    data: {
                        pool_id: pool.id,
                        game_id: dbGame.id,
                        user_id: userId,
                    },
                });
            }

            return pool.id;
        });

        revalidatePath("/randomizer");
        return { success: true, poolId: result };
    } catch (error: any) {
        console.error("Error saving selections:", error);
        return {
            success: false,
            error: "Erro ao salvar sele├º├╡es: " + (error?.message || "Desconhecido"),
        };
    }
}

// ---------- Remove a Single Entry ----------

export async function removeEntry(entryId: string) {
    const session = await auth();
    if (!session?.user?.id) {
        return { success: false, error: "Usu├írio n├úo autenticado" };
    }

    try {
        // Only allow user to remove their own entries
        const entry = await prisma.poolEntry.findUnique({
            where: { id: entryId },
        });

        if (!entry) {
            return { success: false, error: "Entrada n├úo encontrada" };
        }

        if (entry.user_id !== session.user.id) {
            return { success: false, error: "Voc├¬ s├│ pode remover seus pr├│prios jogos" };
        }

        await prisma.poolEntry.delete({ where: { id: entryId } });

        revalidatePath("/randomizer");
        return { success: true };
    } catch (error: any) {
        console.error("Error removing entry:", error);
        return { success: false, error: "Erro ao remover: " + (error?.message || "Desconhecido") };
    }
}

// ---------- Execute Roll (Server-Side) ----------

export async function executeRoll(poolId: string) {
    const session = await auth();
    if (!session?.user?.id) {
        return { success: false, error: "Usu├írio n├úo autenticado" };
    }

    try {
        const result = await prisma.$transaction(async (tx) => {
            const pool = await tx.pool.findUnique({
                where: { id: poolId },
                include: {
                    entries: {
                        include: { game: true },
                    },
                },
            });

            if (!pool) throw new Error("Pool n├úo encontrada");
            if (pool.status !== "OPEN") throw new Error("Pool j├í foi sorteada");
            if (!pool.entries || pool.entries.length === 0) throw new Error("Pool vazia");

            // Verify pool is complete
            const typeEnum = pool.type;
            const maxPerPerson = typeEnum === "MAIN_QUEST" ? 2 : 3;
            const totalRequired = maxPerPerson * 2;

            if (pool.entries.length < totalRequired) {
                throw new Error(`Pool incompleta: ${pool.entries.length}/${totalRequired} jogos`);
            }

            // SERVER-SIDE RANDOM - transparent and unbiased
            const randomIndex = Math.floor(Math.random() * pool.entries.length);
            const winnerEntry = pool.entries[randomIndex];

            // Close pool with winner
            await tx.pool.update({
                where: { id: poolId },
                data: {
                    status: "CLOSED",
                    winner_game_id: winnerEntry.game_id,
                },
            });

            // Get all users to create GameProgress
            const allUsers = await tx.user.findMany();

            // Ensure all pool games have GameProgress for all users
            for (const entry of pool.entries) {
                for (const user of allUsers) {
                    const existing = await tx.gameProgress.findUnique({
                        where: { user_id_game_id: { user_id: user.id, game_id: entry.game_id } },
                    });
                    if (!existing) {
                        await tx.gameProgress.create({
                            data: {
                                user_id: user.id,
                                game_id: entry.game_id,
                                status: "SUGGESTED",
                            },
                        });
                    }
                }
            }

            // Set winner game to ACTIVE for all users
            await tx.gameProgress.updateMany({
                where: { game_id: winnerEntry.game_id },
                data: {
                    status: "ACTIVE",
                    start_date: new Date(),
                },
            });

            return {
                winnerId: winnerEntry.game_id,
                winnerTitle: winnerEntry.game.title,
                winnerImageUrl: winnerEntry.game.cover_url,
            };
        });

        revalidatePath("/randomizer");
        revalidatePath("/");
        return { success: true, ...result };
    } catch (error: any) {
        console.error("Error executing roll:", error);
        return { success: false, error: "Erro no sorteio: " + (error?.message || "Desconhecido") };
    }
}

