function getTimeSince(date: Date | null): string {
    if (!date) return "";
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    if (days === 0) return "Hoje";
    if (days === 1) return "H├í 1 dia";
    return `H├í ${days} dias`;
}

