"use client";

import { useState, useEffect } from "react";
import { Star, BookOpen, ChevronLeft, ChevronRight, Gamepad2 } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { UserLink } from "@/components/ui/user-link";

interface StatsGridProps {
    reviews: {
        id: string;
        rating: number;
        review_text: string | null;
        game: { title: string; cover_url: string | null };
        user: { id: string; name: string | null; username: string | null };
    }[];
}

export function StatsGrid({ reviews }: StatsGridProps) {
    const [currentIndex, setCurrentIndex] = useState(0);
    const [isAnimating, setIsAnimating] = useState(false);

    if (!reviews || reviews.length === 0) {
        return (
            <div
                className="glass-card animate-fade-in-up flex flex-col items-center justify-center rounded-3xl border border-zinc-800/50 bg-zinc-950/40 p-14 text-center backdrop-blur-md"
                style={{ animationDelay: "300ms" }}
            >
                <BookOpen className="mb-6 h-20 w-20 text-zinc-800 drop-shadow-md" />
                <h4 className="text-3xl font-black tracking-tight text-white/90">
                    Nenhuma review dispon├¡vel
                </h4>
                <p className="mt-4 max-w-md text-base font-medium text-zinc-500">
                    Jogue, finalize e conte para os outros aposentados o que achou da sua jornada.
                </p>
            </div>
        );
    }

    const currentReview = reviews[currentIndex];

    const handleNavigation = (direction: "next" | "prev") => {
        if (isAnimating) return;
        setIsAnimating(true);
        setTimeout(() => {
            setCurrentIndex((prev) => {
                if (direction === "next") return prev === reviews.length - 1 ? 0 : prev + 1;
                return prev === 0 ? reviews.length - 1 : prev - 1;
            });
            setTimeout(() => setIsAnimating(false), 50);
        }, 300); // 300ms matches the fade out transition duration
    };

    return (
        <div
            className="group relative w-full overflow-hidden rounded-[2rem] border border-white/5 bg-zinc-950/80 shadow-2xl transition-all duration-700 hover:border-[#bd0df2]/30 hover:shadow-[#bd0df2]/10"
            style={{ animationDelay: "300ms" }}
        >
            {/* Dark/Grain/Glow Background Effects */}
            <div className="absolute inset-0 z-0 bg-gradient-to-br from-zinc-950 via-zinc-900 to-[#12001a]" />
            <div
                className="pointer-events-none absolute inset-0 z-0 opacity-[0.03] mix-blend-overlay"
                style={{ backgroundImage: "url('https://grainy-gradients.vercel.app/noise.svg')" }}
            />

            {/* Dynamic Cover Image Background Overlay */}
            {currentReview.game.cover_url && (
                <div
                    className={`absolute inset-0 z-0 transition-opacity duration-1000 ease-in-out ${isAnimating ? "opacity-0" : "opacity-20 mix-blend-overlay"}`}
                >
                    <Image
                        src={currentReview.game.cover_url.replace("t_cover_big", "t_1080p")}
                        alt={currentReview.game.title}
                        fill
                        className="scale-110 object-cover blur-2xl"
                        priority
                    />
                </div>
            )}

            <div
                className={`relative z-10 flex flex-col transition-opacity duration-300 ease-in-out md:flex-row ${isAnimating ? "scale-[0.98] opacity-0" : "scale-100 opacity-100"}`}
            >
                {/* Left: Huge Cover & Score */}
                <div className="relative flex aspect-[3/4] w-full items-center justify-center overflow-hidden bg-zinc-950/50 p-6 md:aspect-auto md:min-h-[450px] md:w-2/5">
                    {currentReview.game.cover_url ? (
                        <div className="relative h-full max-h-[500px] w-full max-w-[350px] overflow-hidden rounded-xl shadow-[0_0_40px_rgba(0,0,0,0.8)] transition-transform duration-1000 ease-out group-hover:scale-105">
                            <Image
                                src={currentReview.game.cover_url.replace("t_cover_big", "t_1080p")}
                                alt={currentReview.game.title}
                                fill
                                className="object-cover"
                                priority
                            />
                        </div>
                    ) : (
                        <div className="flex h-full w-full items-center justify-center rounded-xl bg-zinc-900/50">
                            <Gamepad2 className="h-24 w-24 text-zinc-800" />
                        </div>
                    )}

                    {/* Gradient overlay to seamlessly merge the image container with the right side */}
                    <div className="pointer-events-none absolute inset-x-0 bottom-0 h-32 bg-gradient-to-t from-zinc-950/95 to-transparent md:inset-y-0 md:right-0 md:left-auto md:h-full md:w-32 md:bg-gradient-to-l" />

                    {/* Neon Score Badge */}
                    <div className="absolute bottom-10 left-10 z-20 flex h-24 w-24 flex-col items-center justify-center rounded-full border border-[#bd0df2]/40 bg-zinc-950/90 shadow-[0_0_30px_rgba(189,13,242,0.4)] backdrop-blur-xl transition-transform hover:scale-110 md:top-10 md:bottom-auto md:left-10">
                        <span className="text-sm font-bold tracking-widest text-[#bd0df2] uppercase">
                            Nota
                        </span>
                        <span className="text-4xl font-black tracking-tighter text-white">
                            {currentReview.rating}
                        </span>
                    </div>
                </div>

                {/* Right: Review Content */}
                <div className="relative flex flex-1 flex-col justify-center bg-zinc-950/80 p-8 backdrop-blur-sm md:p-12 lg:p-16">
                    {/* Header Tag */}
                    <div className="mb-6 flex items-center gap-3">
                        <div className="flex items-center gap-2 rounded-full border border-[#bd0df2]/30 bg-[#bd0df2]/10 px-4 py-1.5 backdrop-blur-md">
                            <Star className="h-4 w-4 text-[#bd0df2]" />
                            <span className="text-xs font-black tracking-[0.2em] text-[#bd0df2] uppercase">
                                Review da Vez
                            </span>
                        </div>

                        {reviews.length > 1 && (
                            <div className="flex items-center gap-2 rounded-full border border-white/5 bg-white/5 px-4 py-1.5 backdrop-blur-md">
                                <span className="text-xs font-bold tracking-widest text-zinc-400">
                                    <span className="text-white">{currentIndex + 1}</span> /{" "}
                                    {reviews.length}
                                </span>
                            </div>
                        )}
                    </div>

                    {/* Game Title */}
                    <h3 className="mb-8 text-4xl leading-[1.1] font-black tracking-tighter text-white drop-shadow-sm md:text-5xl lg:text-6xl">
                        {currentReview.game.title}
                    </h3>

                    {/* Review Text */}
                    <div className="relative mb-10 border-l-2 border-[#bd0df2]/40 pl-6">
                        <p className="text-lg leading-relaxed font-medium text-zinc-300 md:text-xl">
                            {currentReview.review_text
                                ? `"${currentReview.review_text}"`
                                : "O jogador escolheu deixar apenas a nota. O sil├¬ncio, ├ás vezes, fala mais alto."}
                        </p>
                    </div>

                    {/* Footer Info & Actions */}
                    <div className="mt-auto flex flex-col items-start justify-between gap-6 border-t border-white/5 pt-6 sm:flex-row sm:items-center">
                        <div className="flex items-center gap-3">
                            <div className="flex h-10 w-10 items-center justify-center rounded-full border border-white/10 bg-zinc-800 font-black text-zinc-400 uppercase">
                                {currentReview.user.name?.[0] ||
                                    currentReview.user.username?.[0] ||
                                    "?"}
                            </div>
                            <div className="flex flex-col">
                                <span className="text-xs font-bold tracking-widest text-zinc-500 uppercase">
                                    Avaliado por
                                </span>
                                <span className="font-bold text-white transition-colors hover:text-[#bd0df2]">
                                    <UserLink
                                        userId={currentReview.user.id}
                                        name={currentReview.user.name}
                                        username={currentReview.user.username}
                                    />
                                </span>
                            </div>
                        </div>

                        <Link
                            href="/reviews"
                            className="group/link relative flex items-center gap-2 text-sm font-bold tracking-widest text-zinc-400 uppercase transition-colors after:absolute after:bottom-0 after:left-0 after:h-[2px] after:w-0 after:bg-[#bd0df2] after:transition-all hover:text-white hover:after:w-full"
                        >
                            Ver Todas
                            <ChevronRight className="h-4 w-4 transition-transform group-hover/link:translate-x-1" />
                        </Link>
                    </div>
                </div>
            </div>

            {/* Carousel Navigation Floating Buttons */}
            {reviews.length > 1 && (
                <>
                    <button
                        onClick={() => handleNavigation("prev")}
                        disabled={isAnimating}
                        className="absolute top-1/2 left-4 z-20 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-zinc-950/60 text-white backdrop-blur-xl transition-all hover:scale-110 hover:border-[#bd0df2] hover:bg-[#bd0df2] hover:shadow-[0_0_20px_rgba(189,13,242,0.4)] disabled:pointer-events-none disabled:opacity-50"
                    >
                        <ChevronLeft className="h-6 w-6" />
                    </button>
                    <button
                        onClick={() => handleNavigation("next")}
                        disabled={isAnimating}
                        className="absolute top-1/2 right-4 z-20 flex h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-zinc-950/60 text-white backdrop-blur-xl transition-all hover:scale-110 hover:border-[#bd0df2] hover:bg-[#bd0df2] hover:shadow-[0_0_20px_rgba(189,13,242,0.4)] disabled:pointer-events-none disabled:opacity-50"
                    >
                        <ChevronRight className="h-6 w-6" />
                    </button>
                </>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { PlusCircle, Loader2, Trophy, History, Save, Pencil, X, Check } from "lucide-react";
import { GameSearchResult } from "@/components/ui/game-autocomplete";
import { GameAutocomplete } from "@/components/ui/game-autocomplete";
import { getRandomizerStatus } from "@/app/lib/quest-actions";
import {
    getOpenPool,
    saveSelections,
    executeRoll,
    GameSelection,
    PoolEntryData,
} from "@/app/lib/pool-actions";
import { cn } from "@/lib/utils";

type QuestType = "MAIN" | "SIDE";

interface LocalCandidate extends GameSearchResult {
    nominator: string;
    entryId?: string; // From DB if already saved
}

export function RandomizerClient({
    currentUserId,
    currentUserName,
    currentUserEmail,
    canAddGames,
    otherPlayerName: defaultOtherName,
}: {
    currentUserId: string;
    currentUserName: string;
    currentUserEmail: string;
    canAddGames: boolean;
    otherPlayerName: string;
}) {
    const [questType, setQuestType] = useState<QuestType>("SIDE");

    // Pool state
    const [poolId, setPoolId] = useState<string | null>(null);
    const [mySelections, setMySelections] = useState<LocalCandidate[]>([]);
    const [otherSelections, setOtherSelections] = useState<PoolEntryData[]>([]);
    const [isEditing, setIsEditing] = useState(false);
    const [addingGame, setAddingGame] = useState(false);

    // Saved snapshot for cancel
    const [savedSnapshot, setSavedSnapshot] = useState<LocalCandidate[]>([]);

    const [lockStatus, setLockStatus] = useState<{ locked: boolean; message?: string }>({
        locked: false,
    });

    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [isRolling, setIsRolling] = useState(false);
    const [winner, setWinner] = useState<{ title: string; imageUrl?: string | null } | null>(null);
    const [saveStatus, setSaveStatus] = useState<{ success?: boolean; message?: string } | null>(
        null,
    );

    const maxPerPerson = questType === "MAIN" ? 2 : 3;

    // Determine the "other" user's name from pool entries or from the prop
    const otherUserName =
        otherSelections.length > 0 ? otherSelections[0].userName : defaultOtherName;

    const loadPool = useCallback(
        async (type: QuestType) => {
            setIsLoading(true);
            try {
                const pool = await getOpenPool(type);
                if (pool) {
                    setPoolId(pool.poolId);

                    // Split entries: mine vs others
                    const mine = pool.entries
                        .filter((e) => e.userId === currentUserId)
                        .map((e) => ({
                            id: e.gameIgdbId,
                            nome: e.gameTitle,
                            imageUrl: e.gameImageUrl,
                            nominator: currentUserName,
                            entryId: e.id,
                        }));
                    const others = pool.entries.filter((e) => e.userId !== currentUserId);

                    setMySelections(mine);
                    setSavedSnapshot(mine);
                    setOtherSelections(others);
                } else {
                    setPoolId(null);
                    setMySelections([]);
                    setSavedSnapshot([]);
                    setOtherSelections([]);
                }
            } catch (err) {
                console.error("Error loading pool:", err);
            } finally {
                setIsLoading(false);
            }
        },
        [currentUserId, currentUserName],
    );

    useEffect(() => {
        setWinner(null);
        setSaveStatus(null);
        setIsEditing(false);
        setAddingGame(false);

        // Fetch lock status
        getRandomizerStatus(questType === "MAIN" ? "MAIN_QUEST" : "SIDE_QUEST").then((res) => {
            setLockStatus(res as any);
        });

        loadPool(questType);
    }, [questType, loadPool]);

    // --- Handlers ---

    const handleAddGame = (game: GameSearchResult) => {
        if (mySelections.length >= maxPerPerson) return;
        if (mySelections.find((c) => c.nome === game.nome)) return;

        setMySelections((prev) => [...prev, { ...game, nominator: currentUserName }]);
        setAddingGame(false);
    };

    const handleRemoveGame = (index: number) => {
        setMySelections((prev) => prev.filter((_, i) => i !== index));
    };

    const handleSaveSelections = async () => {
        setIsSaving(true);
        setSaveStatus(null);

        try {
            const games: GameSelection[] = mySelections.map((c) => ({
                igdbId: c.id,
                nome: c.nome,
                imageUrl: c.imageUrl,
            }));

            const response = await saveSelections(questType, games);

            if (response.success) {
                setSaveStatus({ success: true, message: "Sele├º├╡es salvas!" });
                setIsEditing(false);
                // Reload pool to get fresh entry IDs
                await loadPool(questType);
            } else {
                setSaveStatus({ success: false, message: response.error || "Erro ao salvar." });
            }
        } catch (err) {
            console.error(err);
            setSaveStatus({ success: false, message: "Erro ao conectar ao servidor." });
        } finally {
            setIsSaving(false);
        }
    };

    const handleStartEditing = () => {
        setSavedSnapshot([...mySelections]);
        setIsEditing(true);
    };

    const handleCancelEditing = () => {
        setMySelections(savedSnapshot);
        setIsEditing(false);
        setAddingGame(false);
    };

    const [cycleText, setCycleText] = useState<string>("");

    const handleRoll = async () => {
        if (!poolId || isRolling || isSaving || lockStatus.locked || winner) return;

        const totalGames = mySelections.length + otherSelections.length;
        const requiredTotal = maxPerPerson * 2;
        if (totalGames < requiredTotal) return;

        setIsRolling(true);
        setWinner(null);
        setSaveStatus(null);

        try {
            // Setup Fast Cycling Animation
            const allCandidates = [
                ...mySelections.map((c) => c.nome),
                ...otherSelections.map((c) => c.gameTitle),
            ];

            let cycleInterval: NodeJS.Timeout;
            if (allCandidates.length > 0) {
                let currentIndex = 0;
                cycleInterval = setInterval(() => {
                    setCycleText(allCandidates[currentIndex]);
                    currentIndex = (currentIndex + 1) % allCandidates.length;
                }, 100); // changes every 100ms
            }

            // Wait for animation
            await new Promise((resolve) => setTimeout(resolve, 3000));

            if (cycleInterval!) clearInterval(cycleInterval);

            const response = await executeRoll(poolId);

            if (response.success) {
                const result = response as {
                    success: true;
                    winnerId: string;
                    winnerTitle: string;
                    winnerImageUrl: string | null;
                };
                // Fetch high res cover similar to reviews/dashboard for cinematic view
                const cinematicImg =
                    result.winnerImageUrl?.replace("t_cover_big", "t_1080p") || null;
                setWinner({
                    title: result.winnerTitle,
                    imageUrl: cinematicImg,
                });
                setSaveStatus({ success: true, message: "Resultado salvo no Cofre!" });
            } else {
                setSaveStatus({ success: false, message: response.error || "Erro no sorteio." });
            }
        } catch (err) {
            console.error(err);
            setSaveStatus({ success: false, message: "Erro fatal ao conectar ao servidor." });
        } finally {
            setIsRolling(false);
            setCycleText("");
        }
    };

    const handleQuestTypeChange = (type: QuestType) => {
        setQuestType(type);
    };

    const handleClearBoard = async () => {
        setWinner(null);
        setSaveStatus(null);
        await loadPool(questType);
    };

    // --- Computed ---
    const totalGames = mySelections.length + otherSelections.length;
    const requiredTotal = maxPerPerson * 2;
    const poolIsComplete = totalGames >= requiredTotal;
    const mySelectionsAreSaved =
        !isEditing &&
        savedSnapshot.length === mySelections.length &&
        savedSnapshot.every((s, i) => s.nome === mySelections[i]?.nome);
    const hasUnsavedChanges =
        isEditing ||
        (mySelections.length > 0 &&
            (savedSnapshot.length !== mySelections.length ||
                !savedSnapshot.every((s, i) => s.nome === mySelections[i]?.nome)));

    return (
        <div className="relative mx-auto min-h-screen w-full px-6 py-8">
            {/* Background effects */}
            <div className="absolute inset-0 z-0 bg-gradient-to-br from-zinc-950 via-zinc-900/50 to-zinc-950" />
            <div
                className="pointer-events-none absolute inset-0 z-0 opacity-[0.03] mix-blend-overlay"
                style={{ backgroundImage: "url('https://grainy-gradients.vercel.app/noise.svg')" }}
            />

            <div className="relative z-10 flex w-full flex-col gap-8">
                {/* Header Area */}
                <div className="flex flex-col justify-between gap-6 border-b border-white/5 pb-8 md:flex-row md:items-end">
                    <div>
                        <h1 className="mb-2 text-4xl font-black tracking-tight text-white lg:text-5xl">
                            THE GREAT RANDOMIZER
                        </h1>
                        <p className="text-lg font-medium tracking-wide text-zinc-400">
                            May the RNG be in your favor, Commander.
                        </p>
                    </div>
                    <div className="inline-flex rounded-2xl border border-white/5 bg-zinc-900/40 p-1.5 shadow-xl backdrop-blur-md">
                        <button
                            onClick={() => handleQuestTypeChange("MAIN")}
                            className={cn(
                                "rounded-xl px-6 py-2.5 text-xs font-bold tracking-wider uppercase transition-all duration-300",
                                questType === "MAIN"
                                    ? "bg-[#bd0df2]/10 text-[#bd0df2] shadow-[0_0_15px_rgba(189,13,242,0.15)] ring-1 ring-[#bd0df2]/30"
                                    : "text-zinc-500 hover:text-white",
                            )}
                        >
                            Main Quest{" "}
                            <span
                                className={cn(
                                    "ml-1 font-normal",
                                    questType === "MAIN" ? "text-[#bd0df2]/60" : "text-zinc-600",
                                )}
                            >
                                (3m)
                            </span>
                        </button>
                        <button
                            onClick={() => handleQuestTypeChange("SIDE")}
                            className={cn(
                                "rounded-xl px-6 py-2.5 text-xs font-bold tracking-wider uppercase transition-all duration-300",
                                questType === "SIDE"
                                    ? "bg-[#bd0df2]/10 text-[#bd0df2] shadow-[0_0_15px_rgba(189,13,242,0.15)] ring-1 ring-[#bd0df2]/30"
                                    : "text-zinc-500 hover:text-white",
                            )}
                        >
                            Side Quest{" "}
                            <span
                                className={cn(
                                    "ml-1 font-normal",
                                    questType === "SIDE" ? "text-[#bd0df2]/60" : "text-zinc-600",
                                )}
                            >
                                (1m)
                            </span>
                        </button>
                    </div>
                </div>

                {/* Alert Notification */}
                {saveStatus && (
                    <div
                        className={cn(
                            "animate-in fade-in slide-in-from-top-4 flex items-center gap-3 rounded-xl border px-4 py-3",
                            saveStatus.success
                                ? "bg-primary/10 border-primary/50 text-white"
                                : "border-red-500/50 bg-red-500/10 text-red-400",
                        )}
                    >
                        <Trophy
                            className={cn(
                                "h-5 w-5",
                                saveStatus.success ? "text-primary" : "text-red-400",
                            )}
                        />
                        <p className="text-sm font-bold">{saveStatus.message}</p>
                    </div>
                )}

                {isLoading ? (
                    <div className="flex items-center justify-center py-20">
                        <Loader2 className="text-primary h-10 w-10 animate-spin" />
                    </div>
                ) : (
                    <div className="grid grid-cols-1 items-start gap-8 lg:grid-cols-2 lg:gap-12 xl:gap-16">
                        {/* Left Column: Candidates Pool */}
                        <div className="flex flex-col gap-6">
                            <div className="flex items-center justify-between">
                                <h3 className="text-sm font-bold tracking-widest text-[#bd0df2]/80 uppercase">
                                    Candidates Pool
                                </h3>
                                <span className="text-sm font-black tracking-widest text-[#bd0df2] drop-shadow-[0_0_8px_rgba(189,13,242,0.3)]">
                                    {totalGames}/{requiredTotal} SELECTED
                                </span>
                            </div>

                            {/* MY Choices */}
                            <div
                                className={`flex flex-col gap-4 rounded-2xl border border-white/5 bg-zinc-900/40 p-6 shadow-2xl backdrop-blur-md transition-colors hover:border-white/10 ${addingGame ? "relative z-50" : "relative z-10"}`}
                            >
                                <div className="mb-2 flex items-center justify-between">
                                    <span className="text-sm font-black tracking-widest text-[#bd0df2] uppercase drop-shadow-[0_0_8px_rgba(189,13,242,0.3)]">
                                        {currentUserName}&apos;s Choices
                                    </span>
                                    <div className="flex items-center gap-2">
                                        <span className="text-sm font-bold text-zinc-500">
                                            {mySelections.length}/{maxPerPerson}
                                        </span>
                                        {canAddGames && !winner && (
                                            <>
                                                {isEditing ? (
                                                    <div className="flex items-center gap-1">
                                                        <button
                                                            onClick={handleCancelEditing}
                                                            className="rounded-lg p-1.5 text-zinc-500 transition-colors hover:bg-zinc-800 hover:text-white"
                                                            title="Cancelar"
                                                        >
                                                            <X className="h-4 w-4" />
                                                        </button>
                                                    </div>
                                                ) : mySelections.length > 0 ? (
                                                    <button
                                                        onClick={handleStartEditing}
                                                        className="rounded-lg p-1.5 text-zinc-500 transition-colors hover:bg-zinc-800 hover:text-white"
                                                        title="Editar sele├º├╡es"
                                                    >
                                                        <Pencil className="h-4 w-4" />
                                                    </button>
                                                ) : null}
                                            </>
                                        )}
                                    </div>
                                </div>

                                {mySelections.map((c, index) => (
                                    <div
                                        key={c.id + "-" + index}
                                        className="group relative flex items-center overflow-hidden rounded-xl border border-white/5 bg-zinc-950/50 p-3 shadow-inner transition-all duration-300 hover:border-[#bd0df2]/40 hover:bg-[#bd0df2]/5 hover:shadow-[0_0_20px_rgba(189,13,242,0.1)]"
                                    >
                                        <div className="mr-4 h-16 w-12 shrink-0 overflow-hidden rounded border border-white/5 bg-zinc-900">
                                            {c.imageUrl && (
                                                <img
                                                    src={c.imageUrl}
                                                    alt={c.nome}
                                                    className="h-full w-full object-cover"
                                                />
                                            )}
                                        </div>
                                        <h4 className="flex-1 truncate text-sm font-black tracking-wide text-white lg:text-base">
                                            {c.nome}
                                        </h4>
                                        {isEditing && (
                                            <button
                                                onClick={() => handleRemoveGame(index)}
                                                className="p-2 text-zinc-500 transition-colors hover:text-red-400"
                                            >
                                                <X className="h-5 w-5" />
                                            </button>
                                        )}
                                    </div>
                                ))}

                                {/* Add game (only in edit mode or when no selections saved yet) */}
                                {canAddGames &&
                                    (isEditing || savedSnapshot.length === 0) &&
                                    mySelections.length < maxPerPerson &&
                                    !winner &&
                                    (addingGame ? (
                                        <div className="mt-3">
                                            <GameAutocomplete
                                                onSelect={handleAddGame}
                                                onCancel={() => setAddingGame(false)}
                                            />
                                        </div>
                                    ) : (
                                        <button
                                            onClick={() => {
                                                if (!isEditing && savedSnapshot.length === 0) {
                                                    setIsEditing(true);
                                                }
                                                setAddingGame(true);
                                            }}
                                            className="w-full rounded-xl border border-dashed border-white/10 py-4 text-sm font-bold text-white/40 transition-all hover:border-white/30 hover:text-white/80"
                                        >
                                            + ADD GAME
                                        </button>
                                    ))}

                                {/* Save button */}
                                {canAddGames &&
                                    (isEditing ||
                                        (savedSnapshot.length === 0 &&
                                            mySelections.length > 0)) && (
                                        <button
                                            onClick={handleSaveSelections}
                                            disabled={isSaving}
                                            className={cn(
                                                "mt-2 flex w-full items-center justify-center gap-2 rounded-xl py-3.5 text-xs font-black tracking-widest uppercase transition-all duration-300",
                                                isSaving
                                                    ? "cursor-not-allowed border border-white/5 bg-zinc-900 text-zinc-500"
