"use client";

import { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { Button } from "@/components/ui/button";
import { Menu, X } from "lucide-react";
import { Sidebar } from "./sidebar";
import { usePathname } from "next/navigation";

export function MobileNav() {
    const [open, setOpen] = useState(false);
    const [mounted, setMounted] = useState(false);
    const pathname = usePathname();

    useEffect(() => {
        setMounted(true);
    }, []);

    // Close menu when route changes
    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setOpen(false);
    }, [pathname]);

    return (
        <>
            <Button
                variant="ghost"
                size="icon"
                className="mr-2 -ml-2 md:hidden"
                onClick={() => setOpen(true)}
            >
                <Menu className="h-5 w-5" />
                <span className="sr-only">Toggle Menu</span>
            </Button>

            {mounted &&
                open &&
                createPortal(
                    <div className="animate-in fade-in-0 fixed inset-0 z-[100] flex bg-black/80 backdrop-blur-sm">
                        <div className="animate-in slide-in-from-left-full relative h-full w-[85%] max-w-xs border-r border-[#bd0df2]/20 duration-300">
                            {/* Mobile Background mirror of Sidebar */}
                            <div className="absolute inset-0 z-0 bg-gradient-to-br from-zinc-950 via-zinc-900/50 to-zinc-950" />
                            <div
                                className="pointer-events-none absolute inset-0 z-0 opacity-[0.03] mix-blend-overlay"
                                style={{
                                    backgroundImage:
                                        "url('https://grainy-gradients.vercel.app/noise.svg')",
                                }}
                            />

                            <Button
                                variant="ghost"
                                size="icon"
                                className="absolute top-4 right-4 z-50 text-zinc-400 hover:bg-zinc-800/50 hover:text-white"
                                onClick={() => setOpen(false)}
                            >
                                <X className="h-5 w-5" />
                                <span className="sr-only">Close Menu</span>
                            </Button>

                            <div className="relative z-10 h-full w-full">
                                <Sidebar className="static flex h-full w-full border-none bg-transparent pt-4 shadow-none" />
                            </div>
                        </div>
                        <div className="flex-1" onClick={() => setOpen(false)} />
                    </div>,
                    document.body,
                )}
        </>
    );
}

"use client";

import { useState, useTransition, useEffect } from "react";
import { Game } from "@prisma/client";
import { GameAutocomplete, GameSearchResult } from "@/components/ui/game-autocomplete";
import Image from "next/image";
import { Heart, Edit2, Check, X, Loader2, Gamepad2 } from "lucide-react";
import { Button } from "@/components/ui/button";

interface FavoriteGamesModuleProps {
    title: string;
    initialFavorites: Game[];
    isOwner?: boolean;
    onSaveAction: (candidates: GameSearchResult[]) => Promise<{ success: boolean; error?: string }>;
}

export function FavoriteGamesModule({
    title,
    initialFavorites,
    isOwner = true,
    onSaveAction,
}: FavoriteGamesModuleProps) {
    const [isEditing, setIsEditing] = useState(false);
    const [isPending, startTransition] = useTransition();
    const [favorites, setFavorites] = useState<GameSearchResult[]>(
        initialFavorites.map((g) => ({
            id: g.id,
            nome: g.title,
            imageUrl: g.cover_url || "",
        })),
    );
    const [prevInitialFavorites, setPrevInitialFavorites] = useState(initialFavorites);
    const [isSearching, setIsSearching] = useState(false);

    if (initialFavorites !== prevInitialFavorites) {
        setPrevInitialFavorites(initialFavorites);
        if (!isEditing) {
            setFavorites(
                initialFavorites.map((g) => ({
                    id: g.id,
                    nome: g.title,
                    imageUrl: g.cover_url || "",
                })),
            );
        }
    }

    const handleSave = () => {
        startTransition(async () => {
            const res = await onSaveAction(favorites);
            if (res.success) {
                setIsEditing(false);
            } else {
                alert(res.error || "Failed to save games.");
            }
        });
    };

    const handleAddGame = (game: GameSearchResult) => {
        if (favorites.length >= 3) return;
        if (favorites.find((f) => f.nome === game.nome)) return;
        setFavorites([...favorites, game]);
        setIsSearching(false);
    };

    const handleRemoveGame = (id: string, nome: string) => {
        setFavorites(favorites.filter((f) => f.id !== id && f.nome !== nome));
    };

    return (
        <div
            className={`rounded-2xl border border-white/5 bg-zinc-900/40 p-6 shadow-2xl backdrop-blur-md transition-colors hover:border-white/10 ${isEditing ? "relative z-50" : "relative z-10"}`}
        >
            <div className="mb-6 flex items-center justify-between">
                <h2 className="flex items-center gap-2 text-sm font-black tracking-widest text-[#bd0df2] uppercase drop-shadow-[0_0_8px_rgba(189,13,242,0.3)]">
                    <Heart className="h-4 w-4 fill-[#bd0df2]/20" />
                    {title}
                </h2>
                {isOwner &&
                    (!isEditing ? (
                        <button
                            onClick={() => setIsEditing(true)}
                            className="rounded-lg p-1.5 text-zinc-500 transition-colors hover:bg-zinc-800 hover:text-white"
                        >
                            <Edit2 className="h-4 w-4" />
                        </button>
                    ) : (
                        <div className="flex gap-2">
                            <button
                                onClick={() => {
                                    setFavorites(
                                        initialFavorites.map((g) => ({
                                            id: g.id,
                                            nome: g.title,
                                            imageUrl: g.cover_url || "",
                                        })),
                                    );
                                    setIsEditing(false);
                                }}
                                className="rounded-lg p-1.5 text-zinc-500 transition-colors hover:bg-red-500/10 hover:text-red-400 disabled:opacity-50"
                                disabled={isPending}
                            >
                                <X className="h-4 w-4" />
                            </button>
                            <button
                                onClick={handleSave}
                                className="rounded-lg p-1.5 text-[#bd0df2] transition-colors hover:bg-[#bd0df2]/10 hover:text-[#bd0df2] disabled:opacity-50"
                                disabled={isPending}
                            >
                                {isPending ? (
                                    <Loader2 className="h-4 w-4 animate-spin" />
                                ) : (
                                    <Check className="h-4 w-4 font-black" />
                                )}
                            </button>
                        </div>
                    ))}
            </div>

            <div className="flex flex-col gap-4">
                {favorites.map((game, idx) => (
                    <div
                        key={`${game.id}-${idx}`}
                        className="group relative flex items-center gap-4 overflow-hidden rounded-xl border border-white/5 bg-zinc-950/50 p-3 shadow-inner transition-all duration-300 hover:border-[#bd0df2]/40 hover:bg-[#bd0df2]/5 hover:shadow-[0_0_20px_rgba(189,13,242,0.1)]"
                    >
                        <div className="relative h-20 w-14 shrink-0 overflow-hidden rounded border border-white/5 bg-zinc-900">
                            {game.imageUrl ? (
                                <Image
                                    src={game.imageUrl}
                                    alt={game.nome}
                                    fill
                                    className="object-cover"
                                    unoptimized
                                />
                            ) : (
                                <div className="flex h-full w-full items-center justify-center p-2 opacity-30">
                                    <Gamepad2 className="h-6 w-6 text-[#bd0df2]" />
                                </div>
                            )}
                            {isEditing && (
                                <div
                                    className="absolute inset-0 flex cursor-pointer items-center justify-center bg-black/80 opacity-0 backdrop-blur-sm transition-opacity group-hover:opacity-100"
                                    onClick={() => handleRemoveGame(game.id, game.nome)}
                                >
                                    <X className="h-6 w-6 text-red-500 drop-shadow-[0_0_5px_rgba(239,68,68,1)]" />
                                </div>
                            )}
                        </div>
                        <div className="flex min-w-0 flex-1 flex-col justify-center">
                            <span className="text-xs font-black tracking-widest text-[#bd0df2]/60 uppercase">
                                RANK #{idx + 1}
                            </span>
                            <span className="truncate text-base font-black tracking-wide text-white">
                                {game.nome}
                            </span>
                        </div>
                    </div>
                ))}

                {favorites.length === 0 && !isEditing && (
                    <div className="flex items-center justify-center rounded-xl border border-dashed border-white/5 bg-zinc-950/30 py-8">
                        <span className="text-xs font-bold tracking-widest text-zinc-600 uppercase">
                            No games selected
                        </span>
                    </div>
                )}

                {isEditing && favorites.length < 3 && (
                    <div className="relative mt-2 text-sm">
                        {isSearching ? (
                            <div className="absolute top-0 left-0 z-50 w-full rounded-xl border border-[#bd0df2]/30 bg-zinc-950 p-2 shadow-2xl">
                                <GameAutocomplete
                                    onSelect={handleAddGame}
                                    onCancel={() => setIsSearching(false)}
                                />
                            </div>
                        ) : (
                            <button
                                onClick={() => setIsSearching(true)}
                                className="w-full rounded-xl border border-dashed border-white/10 py-4 text-sm font-bold text-white/40 transition-all hover:border-[#bd0df2]/40 hover:bg-[#bd0df2]/5 hover:text-[#bd0df2]/80"
                            >
                                + ADD GAME
                            </button>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
}

import { useState } from "react";
import Image from "next/image";
import { ArrowRight, Calendar, Edit, Share2, User, Trash2, Check } from "lucide-react";
import { format } from "date-fns";
import { deleteReview } from "@/app/lib/review-actions";
import { EditReviewModal } from "./EditReviewModal";
import { UserLink } from "@/components/ui/user-link";

export interface ReviewCardProps {
    review: {
        id: string;
        user_id: string; // added to match standard prisma returns
        rating: number;
        review_text: string | null;
        created_at: Date;
        user: {
            name: string | null;
            username: string | null;
        };
        game: {
            title: string;
            cover_url: string | null;
            platform: string | null;
            quest_type: string;
        };
    };
    currentUserId?: string;
    layout?: "grid" | "list";
}

export function ReviewCard({ review, currentUserId, layout = "grid" }: ReviewCardProps) {
    const [isDeleting, setIsDeleting] = useState(false);
    const [isExpanded, setIsExpanded] = useState(false);
    const [isCopied, setIsCopied] = useState(false);
    const formattedDate = format(new Date(review.created_at), "MMM dd, yyyy");
    const reviewerName = review.user.name || review.user.username || "Unknown Gamer";

    const handleDelete = async () => {
        setIsDeleting(true);
        const res = await deleteReview(review.id);
        if (!res.success) {
            console.error(res.error || "Failed to delete review");
            setIsDeleting(false);
        } else {
            window.location.reload();
        }
    };

    const handleShare = () => {
        navigator.clipboard.writeText(
            `${review.game.title} - ${review.rating}/10\n\n"${review.review_text || ""}"`,
        );
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    };

    // Replace the low res cover with high res if available
    const coverUrl = review.game.cover_url?.replace("t_cover_big", "t_1080p") || null;

    return (
        <div
            className={`group relative flex overflow-hidden rounded-2xl border border-white/5 bg-zinc-900/60 shadow-xl backdrop-blur-sm transition-all duration-500 hover:border-[#bd0df2]/30 hover:bg-zinc-900/80 hover:shadow-[0_0_30px_rgba(189,13,242,0.15)] ${layout === "list" ? "h-auto flex-col md:h-[300px] md:flex-row" : "min-h-[450px] flex-col"} ${isDeleting ? "pointer-events-none opacity-50" : ""}`}
        >
            <div
                className={`relative flex items-center justify-center overflow-hidden bg-zinc-950 px-4 py-8 ${layout === "list" ? "aspect-video w-full shrink-0 md:aspect-[3/4] md:w-[280px]" : "min-h-[300px] w-full"}`}
            >
                {coverUrl ? (
                    <>
                        <div className="absolute inset-0 z-0 opacity-40 mix-blend-overlay">
                            <Image
                                src={coverUrl}
                                alt={`${review.game.title} background`}
                                fill
                                className="scale-125 object-cover blur-3xl transition-transform duration-700 group-hover:scale-110"
                            />
                        </div>
                        <div className="absolute inset-0 z-0 bg-gradient-to-t from-zinc-950 via-zinc-950/40 to-transparent" />

                        <div className="relative z-10 aspect-[3/4] h-full max-h-[320px] w-auto overflow-hidden rounded-xl border border-white/10 shadow-[0_0_40px_rgba(0,0,0,0.8)] transition-all duration-500 group-hover:scale-105 group-hover:border-[#bd0df2]/40 group-hover:shadow-[0_0_30px_rgba(189,13,242,0.3)]">
                            <Image
                                src={coverUrl}
                                alt={`Cover of ${review.game.title}`}
                                fill
                                className="object-cover"
                            />
                        </div>
                    </>
                ) : (
                    <div className="z-10 flex h-full w-full items-center justify-center bg-zinc-950">
                        <span className="text-xs font-bold tracking-widest text-[#bd0df2]/50 uppercase">
                            No Image
                        </span>
                    </div>
                )}
                {/* Dark overlay behind rating for readability */}
                <div className="pointer-events-none absolute inset-0 z-10 bg-gradient-to-t from-zinc-950 via-zinc-950/20 to-transparent opacity-80" />

                <div className="absolute top-4 right-4 z-20 flex h-14 w-14 items-center justify-center rounded-xl border border-[#bd0df2]/30 bg-zinc-950/80 shadow-[0_0_20px_rgba(189,13,242,0.4)] backdrop-blur-xl transition-all duration-500 group-hover:scale-110 group-hover:border-[#bd0df2]/60">
                    <span className="text-xl font-black text-white drop-shadow-[0_0_5px_rgba(255,255,255,0.5)]">
                        {review.rating}
                    </span>
                </div>
            </div>

            <div className="z-10 flex flex-1 flex-col p-6">
                <div className="mb-4 flex flex-wrap items-center gap-3">
                    <span className="rounded-md border border-[#bd0df2]/20 bg-[#bd0df2]/10 px-3 py-1 text-[10px] font-black tracking-[0.2em] text-[#bd0df2] uppercase shadow-[0_0_10px_rgba(189,13,242,0.1)]">
                        {review.game.quest_type === "MAIN_QUEST" ? "Main Quest" : "Side Quest"}
                    </span>
                    {review.game.platform && (
                        <span className="rounded-md border border-white/10 bg-zinc-800/50 px-3 py-1 text-[10px] font-black tracking-[0.2em] text-zinc-300 uppercase">
                            {review.game.platform}
                        </span>
                    )}
                </div>

                <h3 className="mb-2 text-2xl leading-tight font-black tracking-tight text-zinc-100 transition-colors duration-300 group-hover:text-white">
                    {review.game.title}
                </h3>

                <div className="mb-6 flex flex-wrap items-center gap-2 text-xs font-bold tracking-wider text-zinc-500 uppercase">
                    <User className="h-3 w-3 text-[#bd0df2]" />
                    <span>
