                    >
                        {isExpanded ? "Mostrar Menos" : "Review Completa"}{" "}
                        <ArrowRight
                            className={`h-3 w-3 transition-transform duration-300 ${isExpanded ? "-rotate-90 group-hover/btn:-translate-y-1" : "group-hover/btn:translate-x-1.5"}`}
                        />
                    </button>
                    <div className="flex items-center gap-4 text-zinc-500">
                        {currentUserId === review.user_id && (
                            <>
                                <EditReviewModal review={review as any} />
                                <button
                                    onClick={handleDelete}
                                    className="transition-colors hover:text-red-500 hover:drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]"
                                    title="Excluir Review"
                                    disabled={isDeleting}
                                >
                                    {isDeleting ? (
                                        <span className="h-4 w-4 animate-spin rounded-full border-2 border-red-500 border-t-transparent"></span>
                                    ) : (
                                        <Trash2 className="h-4 w-4" />
                                    )}
                                </button>
                            </>
                        )}
                        <button
                            onClick={handleShare}
                            className="transition-colors hover:text-[#bd0df2] hover:drop-shadow-[0_0_8px_rgba(189,13,242,0.5)]"
                            title="Compartilhar"
                        >
                            {isCopied ? (
                                <Check className="h-4 w-4 text-green-400" />
                            ) : (
                                <Share2 className="h-4 w-4" />
                            )}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { ReviewCard } from "./ReviewCard";
import { AddReviewModal } from "./AddReviewModal";
import { Grid, List, Plus } from "lucide-react";

export interface ReviewsClientProps {
    reviews: any[]; // Adjust type based on Prisma include
    games: any[];
    currentUserId?: string;
}

export function ReviewsClient({ reviews, games, currentUserId }: ReviewsClientProps) {
    const [viewMode, setViewMode] = useState<"grid" | "list">("grid");
    const [filterType, setFilterType] = useState<"ALL" | "MAIN_QUEST" | "SIDE_QUEST">("ALL");
    const [sortBy, setSortBy] = useState<"NEWEST" | "HIGHEST_RATED">("NEWEST");
    const [filterUser, setFilterUser] = useState<string>("ALL");

    // Extrair usu├írios ├║nicos que t├¬m reviews
    const uniqueUsers = Array.from(
        new Map(
            reviews.map((r) => [
                r.user_id,
                { id: r.user_id, name: r.user.name, username: r.user.username },
            ]),
        ).values(),
    );

    // Filtrar e Organizar reviews
    const filteredReviews = reviews
        .filter((review) => {
            if (filterType !== "ALL" && review.game.quest_type !== filterType) return false;
            if (filterUser !== "ALL" && review.user_id !== filterUser) return false;
            return true;
        })
        .sort((a, b) => {
            if (sortBy === "HIGHEST_RATED") {
                // If ratings are equal, prioritize newest
                if (b.rating === a.rating) {
                    return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
                }
                return b.rating - a.rating;
            }
            // NEWEST by default
            return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
        });

    return (
        <div className="relative mx-auto min-h-screen w-full px-6 py-8">
            {/* Background effects */}
